const SETTING_OPTIONS={font:['normal','large','xlarge'],spacing:['normal','relaxed'],theme:['light','dark','system'],preference:['balanced','work','family','writing','parenting']};
const SETTING_DEFAULTS={font:'normal',spacing:'normal',theme:'light',preference:'balanced'};
function cleanSettings(value){return Object.fromEntries(Object.entries(SETTING_DEFAULTS).map(([key,fallback])=>[key,SETTING_OPTIONS[key].includes(value?.[key])?value[key]:fallback]))}
let settings=cleanSettings(state.settings),pendingBackup=null;
function preferenceScore(q){if(settings.preference==='parenting')return q.parenting?20:0;const text=q.quote+' '+(q.dialogue?.scene||'');if(settings.preference==='work')return (q.workplace?20:0)+(q.category==='說話的藝術'?3:0)+(/工作|同事|團隊|合作|進度|方案|職場/.test(text)?5:0);if(settings.preference==='family')return (q.category==='好好說話'?3:0)+(/家人|朋友|伴侶|長輩|安慰|關係/.test(text)?5:0);if(settings.preference==='writing')return (q.category==='文字素養'?5:0)+(/寫|文字|句子|文章|比喻|段落/.test(text)?3:0);return 0;}
function applySettings(){if(document.documentElement){document.documentElement.dataset.font=settings.font;document.documentElement.dataset.spacing=settings.spacing;document.documentElement.dataset.theme=settings.theme;}for(const [key,id] of Object.entries({font:'#fontSetting',spacing:'#spacingSetting',theme:'#themeSetting',preference:'#preferenceSetting'}))$(id).value=settings[key];}
for(const [key,id] of Object.entries({font:'#fontSetting',spacing:'#spacingSetting',theme:'#themeSetting',preference:'#preferenceSetting'}))$(id).onchange=()=>{const next=$(id).value;if(!SETTING_OPTIONS[key].includes(next))return;settings[key]=next;applySettings();daily=plannedDaily(selectedDate);persist();render();};
function backupPayload(){return {format:'shiju-backup',version:1,exportedAt:new Date().toISOString(),data:{saved:[...saved],notes:{...notes},labels:{...labels},practice:$('#practiceText').value,reviewHistory:{...reviewHistory},settings:{...settings},readingLog,feedback,practiceHistory,practiceDraft:{...practiceDraft,before:$('#practiceBefore').value},lastExportAt,weeklyGoals,libraryEdition:6000,readingSchedules,practiceUseRecords}}}
function parseBackup(raw){
 if(!raw||raw.format!=='shiju-backup'||raw.version!==1||!raw.data||typeof raw.data!=='object'||Array.isArray(raw.data))throw Error('不是支援的拾句備份格式，請選擇由「匯出備份 JSON」產生的檔案。');
 const input=raw.data;let importedSchedules=validateReadingSchedules(input.readingSchedules);if(input.libraryEdition!==6000)importedSchedules=withLegacySchedules(input.readingLog,importedSchedules);if(!Array.isArray(input.saved)||input.saved.length>10000)throw Error('備份的收藏清單格式不正確。');
 const validId=id=>Number.isInteger(id)&&quoteIndex.has(id);const ids=input.saved.filter(validId);let skipped=input.saved.length-ids.length;
 const dict=(value,validator)=>{if(value===undefined)return {};if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length>10000)throw Error('備份的心得或標籤格式不正確。');const result={};for(const [id,item] of Object.entries(value)){if(!/^\d+$/.test(id)||!validId(Number(id))){skipped++;continue}if(!validator(item))throw Error('備份內容過長或格式不正確，未匯入任何資料。');result[Number(id)]=item}return result};
 const importedNotes=dict(input.notes,v=>typeof v==='string'&&v.length<=2000);
 const importedLabels=dict(input.labels,v=>Array.isArray(v)&&v.length<=30&&v.every(t=>typeof t==='string'&&tagOptions.slice(1).includes(t)));
 const histories=dict(input.reviewHistory,v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v);
 if(input.practice!==undefined&&(typeof input.practice!=='string'||input.practice.length>200000))throw Error('備份中的練習內容格式不正確或過長。');
 return {saved:[...new Set(ids)],notes:importedNotes,labels:importedLabels,practice:input.practice||'',reviewHistory:histories,settings:cleanSettings(input.settings),readingSchedules:importedSchedules,readingLog:validateReadingLog(input.readingLog,importedSchedules),feedback:validateFeedback(input.feedback),practiceHistory:validatePracticeHistory(input.practiceHistory),practiceDraft:validatePracticeDraft(input.practiceDraft),practiceUseRecords:validatePracticeUseRecords(input.practiceUseRecords),weeklyGoals:validateWeeklyGoals(input.weeklyGoals),lastExportAt:isTimestamp(input.lastExportAt)?input.lastExportAt:isTimestamp(raw.exportedAt)?raw.exportedAt:null,skipped};
}
function mergeBackup(incoming){const combinedNotes={...incoming.notes,...Object.fromEntries(Object.entries(notes).filter(([,v])=>v))};const combinedLabels={...labels};for(const [id,items] of Object.entries(incoming.labels))combinedLabels[id]=[...new Set([...(Array.isArray(combinedLabels[id])?combinedLabels[id]:[]),...items])];const current=$('#practiceText').value;const combinedPractice=!incoming.practice||current===incoming.practice||current.includes('\n\n—— 匯入的練習 ——\n'+incoming.practice)?current:!current?incoming.practice:current+'\n\n—— 匯入的練習 ——\n'+incoming.practice;if(combinedPractice.length>200000)throw Error('合併後的練習超過可匯入長度，請先另外保存較長的練習。');const histories={...reviewHistory};for(const [id,date] of Object.entries(incoming.reviewHistory))if(!histories[id]||date>histories[id])histories[id]=date;return {saved:[...new Set([...saved,...incoming.saved])],notes:combinedNotes,labels:combinedLabels,practice:combinedPractice,reviewHistory:histories,settings:$('#importSettings').checked?incoming.settings:settings,readingSchedules:{...incoming.readingSchedules,...readingSchedules},readingLog:mergeReadingLogs(readingLog,incoming.readingLog,{...incoming.readingSchedules,...readingSchedules}),feedback:{...incoming.feedback,...feedback},practiceHistory:mergePracticeHistories(practiceHistory,incoming.practiceHistory),practiceDraft:current||practiceDraft.before||practiceDraft.prompt?practiceDraft:incoming.practiceDraft,practiceUseRecords:mergePracticeUseRecords(practiceUseRecords,incoming.practiceUseRecords),weeklyGoals:{...incoming.weeklyGoals,...weeklyGoals},lastExportAt:[lastExportAt,incoming.lastExportAt].filter(Boolean).sort().at(-1)||null};}
$('#exportBackup').onclick=()=>{try{const blob=new Blob([JSON.stringify(backupPayload(),null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`拾句備份-${day}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);lastExportAt=new Date().toISOString();persist();renderVersionInfo();$('#backupStatus').textContent='已產生備份下載，請確認檔案已儲存。'}catch{$('#backupStatus').textContent='無法產生備份下載，請檢查瀏覽器的下載設定。'}};
$('#importBackup').onchange=async()=>{pendingBackup=null;$('#importPreview').hidden=true;const file=$('#importBackup').files?.[0];if(!file)return;try{if(!bank.length)throw Error('句庫尚未載入，請稍後再匯入。');if(file.size>20*1024*1024)throw Error('備份檔超過 20 MB，未匯入任何資料。');const parsed=parseBackup(JSON.parse(await file.text()));pendingBackup=parsed;const scheduleConflicts=Object.keys(parsed.readingSchedules).filter(date=>readingSchedules[date]&&[...readingSchedules[date]].sort((a,b)=>a-b).join(',')!==[...parsed.readingSchedules[date]].sort((a,b)=>a-b).join(',')).length;const conflicts=Object.keys(parsed.notes).filter(id=>notes[id]&&notes[id]!==parsed.notes[id]).length;$('#importSummary').textContent=`備份含 ${parsed.saved.length} 則收藏、${Object.keys(parsed.notes).length} 則心得、${parsed.practiceHistory.length} 筆練習歷史、${parsed.practiceUseRecords.length} 筆使用經驗、${Object.keys(parsed.readingLog).length} 天已讀紀錄與 ${Object.keys(parsed.feedback).length} 則回饋。${conflicts} 則心得與目前內容不同，將保留目前版本。${scheduleConflicts?` ${scheduleConflicts} 天排程與目前版本不同，將保留目前排程與可對應的已讀進度。`:''}${parsed.skipped?` ${parsed.skipped} 項無法對應目前句庫的資料將略過。`:''}`;$('#importPreview').hidden=false;$('#backupStatus').textContent='請核對預覽，再按「合併匯入」。'}catch(error){$('#backupStatus').textContent=error instanceof SyntaxError?'檔案不是有效的 JSON，未匯入任何資料。':error.message;}finally{$('#importBackup').value=''}};
$('#confirmImport').onclick=()=>{if(!pendingBackup)return;try{const merged=mergeBackup(pendingBackup);const candidate={practiceUseRecords:merged.practiceUseRecords,libraryEdition:6000,readingSchedules:merged.readingSchedules,weeklyGoals:merged.weeklyGoals,restoreReceipt:{at:new Date().toISOString(),saved:merged.saved.length,notes:Object.keys(merged.notes).length,practiceHistory:merged.practiceHistory.length,readingDays:Object.keys(merged.readingLog).length,feedback:Object.keys(merged.feedback).length,skipped:pendingBackup.skipped,practiceUses:merged.practiceUseRecords.length},readingLog:merged.readingLog,feedback:merged.feedback,practiceHistory:merged.practiceHistory,practiceDraft:merged.practiceDraft,lastExportAt:merged.lastExportAt,saved:merged.saved,notes:merged.notes,labels:merged.labels,practice:merged.practice,reviewHistory:merged.reviewHistory,settings:merged.settings,read:merged.readingLog[day]||[],day,edition:4,reviewed};localStorage.setItem('shiju-v1',JSON.stringify(candidate));saved=merged.saved;notes=merged.notes;labels=merged.labels;practice=merged.practice;reviewHistory=merged.reviewHistory;settings=merged.settings;readingSchedules=merged.readingSchedules;readingLog=merged.readingLog;feedback=merged.feedback;practiceHistory=merged.practiceHistory;practiceDraft=merged.practiceDraft;lastExportAt=merged.lastExportAt;weeklyGoals=merged.weeklyGoals;practiceUseRecords=merged.practiceUseRecords;restoreReceipt=candidate.restoreReceipt;read=readingLog[selectedDate]||[];$('#practiceBefore').value=practiceDraft.before;$('#practiceText').value=practice;pendingBackup=null;$('#importPreview').hidden=true;applySettings();daily=plannedDaily(selectedDate);render();$('#backupStatus').textContent='備份已合併，原有收藏與心得已保留。'}catch(error){$('#backupStatus').textContent='未匯入任何資料。'+(error.message.includes('合併後')?error.message:'瀏覽器可能沒有足夠儲存空間，請先匯出目前資料。')}};
$('#cancelImport').onclick=()=>{pendingBackup=null;$('#importPreview').hidden=true;$('#backupStatus').textContent='已取消匯入，目前資料未變更。'};


const FEEDBACK_LABELS={inspiring:'有啟發',ordinary:'較普通',source_question:'出處疑問'};
let practiceHistoryLimit=20;
function validDay(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value}
function isTimestamp(value){return typeof value==='string'&&value.length<=40&&!Number.isNaN(Date.parse(value))&&/^\d{4}-\d{2}-\d{2}T/.test(value)}
function shiftDay(value,offset){return new Date(Date.parse(value)+offset*86400000).toISOString().slice(0,10)}
function validQuoteId(id){return Number.isInteger(id)&&id>=0&&id<6000}
function requireMap(value,name){if(value===undefined)return {};if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length>10000)throw Error(name+'格式不正確。');return value}
function validateReadingLog(value,schedules=readingSchedules){const result={};for(const [date,ids] of Object.entries(requireMap(value,'閱讀紀錄'))){if(!validDay(date)||!Array.isArray(ids)||ids.length>20||!ids.every(validQuoteId))throw Error('閱讀紀錄格式不正確。');const expected=bank.length?new Set(schedules[date]||selectDaily(Math.floor(Date.parse(date)/86400000)).map(q=>q.id)):null;result[date]=[...new Set(ids)].filter(id=>!expected||expected.has(id));}return result}
function cleanReadingLog(value){try{return validateReadingLog(value)}catch{return {}}}
function validateFeedback(value){const result={};for(const [id,item] of Object.entries(requireMap(value,'金句回饋'))){if(!/^\d+$/.test(id)||!validQuoteId(Number(id)))continue;if(!item||!['inspiring','ordinary','source_question'].includes(item.rating)||typeof item.note!=='string'||item.note.length>1000||!isTimestamp(item.updatedAt))throw Error('金句回饋格式不正確。');result[id]={rating:item.rating,note:item.note,updatedAt:item.updatedAt};}return result}
function cleanFeedback(value){try{return validateFeedback(value)}catch{return {}}}
function validatePracticeDraft(value){if(value===undefined)return {before:'',prompt:'',quoteId:null};if(!value||typeof value!=='object'||Array.isArray(value)||typeof value.before!=='string'||value.before.length>20000||typeof value.prompt!=='string'||value.prompt.length>2000||!(value.quoteId===null||validQuoteId(value.quoteId)))throw Error('練習草稿格式不正確。');return {before:value.before,prompt:value.prompt,quoteId:value.quoteId}}
function cleanPracticeDraft(value){try{return validatePracticeDraft(value)}catch{return {before:'',prompt:'',quoteId:null}}}
function validatePracticeHistory(value){if(value===undefined)return [];if(!Array.isArray(value)||value.length>1000)throw Error('練習歷史格式不正確或超過 1,000 筆。');return value.map(item=>{if(!item||typeof item.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(item.id)||!isTimestamp(item.createdAt)||typeof item.before!=='string'||item.before.length>20000||typeof item.after!=='string'||item.after.length>200000||typeof item.prompt!=='string'||item.prompt.length>2000||!(item.quoteId===null||validQuoteId(item.quoteId)))throw Error('練習歷史格式不正確。');return {id:item.id,createdAt:item.createdAt,before:item.before,after:item.after,prompt:item.prompt,quoteId:item.quoteId,automatic:item.automatic===true};})}
function cleanPracticeHistory(value){try{return validatePracticeHistory(value)}catch{return []}}
function practiceKey(item){return JSON.stringify([item.before,item.after,item.prompt,item.quoteId])}
function mergePracticeHistories(current,incoming){const ids=new Set(current.map(r=>r.id)),keys=new Set(current.map(practiceKey));const merged=[...current];for(const item of incoming||[]){if(ids.has(item.id)||keys.has(practiceKey(item)))continue;merged.push(item);ids.add(item.id);keys.add(practiceKey(item));}if(merged.length>1000)throw Error('合併後練習歷史超過 1,000 筆，未匯入。');return merged.sort((a,b)=>a.createdAt.localeCompare(b.createdAt));}
function mergeReadingLogs(current,incoming,schedules=readingSchedules){const result={...current};for(const [date,ids] of Object.entries(incoming||{})){const expected=new Set(schedules[date]||selectDaily(Math.floor(Date.parse(date)/86400000)).map(q=>q.id));result[date]=[...new Set([...(result[date]||[]),...ids])].filter(id=>expected.has(id));}return validateReadingLog(result,schedules)}
function renderVersionInfo(){const labels=Object.values(feedback);$('#versionInfo').textContent=`App ${APP_VERSION} · 句庫 ${LIBRARY_VERSION} · ${bank.length||6000} 則 · 四類各 1,500 則`;
$('#lastBackupInfo').textContent=lastExportAt?'上次產生備份：'+new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',dateStyle:'medium',timeStyle:'short'}).format(new Date(lastExportAt)):'尚未產生備份。';const hasData=saved.length||practiceHistory.length||practice||practiceDraft.before||Object.keys(readingLog).length||Object.keys(feedback).length||Object.keys(notes).length;$('#backupReminder').textContent=!hasData?'開始收藏或練習後，記得定期匯出備份。':!lastExportAt?'你已累積個人資料，建議現在匯出第一份備份。':Date.now()-Date.parse(lastExportAt)>7*86400000?'距離上次備份已超過七天，建議更新備份。':'更新離線版或換裝置前，請再匯出最新備份。';$('#feedbackSummary').textContent=`我的回饋：有啟發 ${labels.filter(x=>x.rating==='inspiring').length} · 較普通 ${labels.filter(x=>x.rating==='ordinary').length} · 出處疑問 ${labels.filter(x=>x.rating==='source_question').length}`;}
$('#feedbackFilter').value='all';$('#feedbackFilter').onchange=()=>{page=0;render()};
function saveQuoteFeedback(id){const rating=$('#quoteRating').value,note=$('#feedbackNote').value.trim();if(!rating&&note){toast('請先選擇一種回饋類型。');return}if(note.length>1000||rating&&!Object.hasOwn(FEEDBACK_LABELS,rating)){toast('回饋格式不正確。');return}const next={...feedback};if(rating)next[id]={rating,note,updatedAt:new Date().toISOString()};else delete next[id];try{localStorage.setItem('shiju-v1',JSON.stringify({...snapshot(),feedback:next}));feedback=next;render();toast(rating?'回饋已儲存於本機，也會納入備份。':'已取消這句的回饋。')}catch{toast('回饋未儲存，請確認瀏覽器儲存空間。')}}
function archivePractice(automatic){const before=$('#practiceBefore').value,after=$('#practiceText').value;if(!before.trim()&&!after.trim()){if(!automatic)toast('先寫下原本的說法或改寫，再儲存練習。');return automatic}const item={id:Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10),createdAt:new Date().toISOString(),before,after,prompt:practiceDraft.prompt,quoteId:practiceDraft.quoteId,automatic};try{const checked=validatePracticeHistory([item])[0];const next=mergePracticeHistories(practiceHistory,[checked]);const nextDraft={...practiceDraft,before};localStorage.setItem('shiju-v1',JSON.stringify({...snapshot(),practice:after,practiceHistory:next,practiceDraft:nextDraft}));practice=after;practiceDraft=nextDraft;practiceHistory=next;return true}catch{toast('練習未儲存，原草稿仍保留。請檢查長度或瀏覽器儲存空間。');return false}}
function renderPracticeHistory(){const quote=practiceDraft.quoteId===null?null:itemById(practiceDraft.quoteId);$('#practicePrompt').textContent=(quote?'「'+quote.quote+'」\n':'')+practiceDraft.prompt;const items=[...practiceHistory].reverse().slice(0,practiceHistoryLimit);$('#practiceHistory').innerHTML=items.length?items.map(item=>`<details class="practice-record"><summary>${escapeHTML(new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',dateStyle:'medium',timeStyle:'short'}).format(new Date(item.createdAt)))} · ${item.automatic?'保留的草稿':'已儲存練習'}</summary><p>${escapeHTML(item.prompt)}</p><div class="practice-comparison"><div><h4>原本會怎麼說</h4><p>${escapeHTML(item.before||'（尚未填寫）')}</p></div><div><h4>改寫後怎麼說</h4><p>${escapeHTML(item.after||'（尚未填寫）')}</p></div></div><button class="quiet" data-restore-practice="${escapeHTML(item.id)}">帶回草稿繼續練習</button><button class="quiet" data-log-use="${escapeHTML(item.id)}">記錄實際使用</button></details>`).join('')+(practiceHistory.length>items.length?'<button class="quiet" data-more-practice>載入更多練習</button>':''):'<p class="empty">還沒有練習紀錄。儲存一次改寫，留下表達的進步。</p>';renderPracticeUses();}
$('#practiceHistory').addEventListener('click',e=>{const use=e.target.closest('[data-log-use]');if(use){openPracticeUse(use.dataset.logUse);return}if(e.target.closest('[data-more-practice]')){practiceHistoryLimit+=20;renderPracticeHistory();return}const b=e.target.closest('[data-restore-practice]');if(!b)return;const item=practiceHistory.find(r=>r.id===b.dataset.restorePractice);if(!item||!archivePractice(true))return;practice=item.after;practiceDraft={before:item.before,prompt:item.prompt,quoteId:item.quoteId};$('#practiceBefore').value=item.before;$('#practiceText').value=item.after;persist();renderPracticeHistory();toast('已帶回草稿，原有歷史仍保留。')});
$('#practiceBefore').oninput=()=>{practiceDraft={...practiceDraft,before:$('#practiceBefore').value};practice=$('#practiceText').value;persist()};$('#practiceText').oninput=()=>{practice=$('#practiceText').value;persist()};


function recommendationScore(q){const value=q.selectionWeight??(q.curated?40:20);return value+preferenceScore(q)*4+(feedback[q.id]?.rating==='inspiring'?100:feedback[q.id]?.rating==='ordinary'?-80:feedback[q.id]?.rating==='source_question'?-10000:0)}
function essentialPicks(items){const eligible=items.filter(q=>feedback[q.id]?.rating!=='source_question').sort((a,b)=>recommendationScore(b)-recommendationScore(a)||a.id-b.id);const selected=[],families=new Set(),types=new Set();for(const q of eligible){const family=q.familyKey||q.id;if(types.has(q.kind)||families.has(family))continue;selected.push(q);families.add(family);types.add(q.kind);if(selected.length===3)return selected}for(const q of eligible){if(selected.includes(q)||families.has(q.familyKey||q.id))continue;selected.push(q);families.add(q.familyKey||q.id);if(selected.length===3)break}return selected;}
function renderEssentials(){const picks=essentialPicks(daily),steps=['讀懂一句','看生活例子','練習改寫'];$('#essentialPanel').innerHTML=`<div class="essential-heading"><div><h2 id="essentialHeading">${picks.length===3?"今天，先留住這三句。":picks.length?"今天，先留住這幾句。":"先核對，再推薦。"}</h2><p>從今日 20 則中挑選 · 不另加句數 · ${picks.length?`已讀 ${picks.filter(q=>read.includes(q.id)).length} / ${picks.length}`:"出處疑問暫停推薦"}</p></div><span>忙碌時，也留一點給自己</span></div><div class="essential-cards">${picks.length?picks.map((q,i)=>`<article><span class="tag">${steps[i]} · ${q.kind}</span><h3>${escapeHTML(q.quote)}</h3><p>${escapeHTML(i===1?q.dialogue.scene:i===2?q.exercise:q.plainMeaning||q.insight)}</p><button class="text-button" ${i===2?'data-core-practice':'data-detail'}="${q.id}">${i===2?'開始這句的改寫':'讀解與生活練習'}</button></article>`).join(''):'<p>今日句子都被標記出處疑問，先核對原文，或調整回饋後再推薦。</p>'}</div>`;}
$('#essentialPanel').addEventListener('click',e=>{const practiceButton=e.target.closest('[data-core-practice]');if(practiceButton){openDetail(Number(practiceButton.dataset.corePractice));$('#useExercise').onclick();return}handleQuoteClick(e)});
function weekStart(date){const weekday=new Date(Date.parse(date)).getUTCDay();return shiftDay(date,-((weekday+6)%7))}
function toTaipeiDay(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value))}
function validateWeeklyGoals(value){const result={};for(const [date,item] of Object.entries(requireMap(value,'每週目標'))){if(!validDay(date)||weekStart(date)!==date||!item||!tagOptions.slice(1).includes(item.topic)||typeof item.note!=='string'||item.note.length>500||!isTimestamp(item.updatedAt))throw Error('每週目標格式不正確。');result[date]={topic:item.topic,note:item.note,updatedAt:item.updatedAt};}return result}
function cleanWeeklyGoals(value){try{return validateWeeklyGoals(value)}catch{return {}}}
function cleanRestoreReceipt(value){const fields=['saved','notes','practiceHistory','readingDays','feedback','skipped'];if(!value||!isTimestamp(value.at)||!fields.every(k=>Number.isInteger(value[k])&&value[k]>=0&&value[k]<=10000))return null;return {...Object.fromEntries(['at',...fields].map(k=>[k,value[k]])),practiceUses:Number.isInteger(value.practiceUses)&&value.practiceUses>=0&&value.practiceUses<=1000?value.practiceUses:0};}
function weeklySummary(offset=0){const start=shiftDay(weekStart(day),offset*7),end=shiftDay(start,6),until=end>day?day:end;const reads=Object.entries(readingLog).filter(([d])=>d>=start&&d<=until);const records=practiceHistory.filter(r=>!r.automatic&&(r.before.trim()||r.after.trim())&&toTaipeiDay(r.createdAt)>=start&&toTaipeiDay(r.createdAt)<=until).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const themeCounts=categories.map(category=>({category,count:saved.map(itemById).filter(q=>q?.category===category).length})).sort((a,b)=>b.count-a.count);return {start,end,until,readDays:reads.filter(([,ids])=>ids.length).length,readCount:reads.reduce((n,[,ids])=>n+ids.length,0),records,useRecords:practiceUseRecords.filter(r=>r.usedOn>=start&&r.usedOn<=until).sort((a,b)=>b.usedOn.localeCompare(a.usedOn)||b.createdAt.localeCompare(a.createdAt)),themeCounts,nextWeek:shiftDay(start,7)};}
function renderWeekly(){const summary=weeklySummary(weekOffset),goal=weeklyGoals[summary.nextWeek]||{topic:'提問',note:''};$('#weeklyPanel').innerHTML=`<div class="weekly-heading"><div class="eyebrow">LOOK BACK, GROW FORWARD</div><h1 id="weeklyHeading">把這一週，讀成自己的話。</h1><p>${summary.start} 至 ${summary.end}（台北時間）</p><div><button class="quiet" data-week="-1" ${weekOffset<=-51?'disabled':''}>前一週</button><button class="quiet" data-week="1" ${weekOffset>=0?'disabled':''}>後一週</button></div></div><div class="weekly-stats"><div><strong>${summary.readDays}</strong><span>有閱讀的日子</span></div><div><strong>${summary.readCount}</strong><span>開啟過讀解的句子</span></div><div><strong>${summary.records.length}</strong><span>儲存的改寫</span></div><div><strong>${summary.useRecords.length}</strong><span>實際嘗試的次數</span></div></div><section class="weekly-card"><h2>目前收藏，偏愛哪些主題？</h2><p>依目前所有收藏計算，不代表這一週新增的收藏。</p>${saved.length?summary.themeCounts.map(t=>`<div class="theme-tally"><span>${t.category}</span><progress max="${Math.max(1,saved.length)}" value="${t.count}"></progress><span>${t.count} 則</span></div>`).join(''):'<p>還沒有收藏。遇到讓你停下來的句子，就先留下。</p>'}</section><section class="weekly-card"><h2>重看自己的三組改寫</h2><p>本週最近三筆手動儲存的練習；自動保留的草稿另留在練習歷史。</p>${summary.records.length?summary.records.slice(0,3).map(r=>`<div class="practice-comparison"><div><h3>原本會怎麼說</h3><p>${escapeHTML(r.before||'（尚未填寫）')}</p></div><div><h3>改寫後怎麼說</h3><p>${escapeHTML(r.after||'（尚未填寫）')}</p></div></div>`).join(''):'<p>本週還沒有儲存的改寫。從今天的一句練習開始。</p>'}<button class="text-button" id="weeklyPractice">到表達練習</button></section><section class="weekly-card"><h2>這一週，真的用上了什麼？</h2>${summary.useRecords.length?summary.useRecords.slice(0,3).map(use=>`<article class="use-record"><h3>${escapeHTML(use.usedOn)} · ${escapeHTML(use.situation)}</h3><p><b>對方的回應：</b>${escapeHTML(use.response||"（尚未記錄）")}</p><p><b>下次調整：</b>${escapeHTML(use.next||"（尚未記錄）")}</p></article>`).join(""):"<p>還沒有記錄實際使用經驗。練習歷史中的「記錄實際使用」可以留下觀察。</p>"}</section><section class="weekly-card"><h2>下一週，想練習什麼？</h2><p>目標週：${summary.nextWeek} 至 ${shiftDay(summary.nextWeek,6)}</p><label>練習情境<select id="weeklyTopic">${tagOptions.slice(1).map(t=>`<option ${goal.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label for="weeklyGoal">留一個具體的小行動</label><textarea id="weeklyGoal" maxlength="500" placeholder="例如：提出不同意見前，先確認對方的考量。">${escapeHTML(goal.note)}</textarea><button class="primary" id="saveWeeklyGoal">儲存下週目標</button><p id="weeklyGoalStatus" role="status"></p></section>`;$('#weeklyPractice').onclick=()=>setView('practice');$('#saveWeeklyGoal').onclick=()=>{const note=$('#weeklyGoal').value.trim(),topic=$('#weeklyTopic').value;if(note.length>500||!tagOptions.slice(1).includes(topic)){toast('請檢查目標內容。');return}const next={...weeklyGoals,[summary.nextWeek]:{topic,note,updatedAt:new Date().toISOString()}};try{localStorage.setItem('shiju-v1',JSON.stringify({...snapshot(),weeklyGoals:next}));weeklyGoals=next;$('#weeklyGoalStatus').textContent='下週目標已儲存，也會納入備份。'}catch{$('#weeklyGoalStatus').textContent='未儲存，請檢查瀏覽器儲存空間。'}};}
$('#weeklyPanel').addEventListener('click',e=>{const b=e.target.closest('[data-week]');if(!b)return;weekOffset=Math.max(-51,Math.min(0,weekOffset+Number(b.dataset.week)));renderWeekly()});
function renderUpdateGuide(){const fresh=lastExportAt&&toTaipeiDay(lastExportAt)===day;$('#updateBackupStatus').textContent=fresh?'今天已產生過備份。請確認下載檔已保存，再下載新版。':'建議先匯出一份最新備份，再下載新版；舊離線檔請先保留。';$('#restoreReceipt').textContent=restoreReceipt?`上次合併完成，目前資料：收藏 ${restoreReceipt.saved} 則、心得 ${restoreReceipt.notes} 則、練習歷史 ${restoreReceipt.practiceHistory} 筆、按日已讀 ${restoreReceipt.readingDays} 天、回饋 ${restoreReceipt.feedback} 則、使用經驗 ${restoreReceipt.practiceUses||0} 筆；略過 ${restoreReceipt.skipped} 項。請核對是否符合預期。`:'';if(!latestVersionInfo)$('#updateInfo').textContent=`目前這份 App 為 ${APP_VERSION}。離線時無法確認發布版本，可連線後按「確認發布版本」。`;}
const renderVersionBase=renderVersionInfo;renderVersionInfo=function(){renderVersionBase();renderUpdateGuide();renderOfflineStatus()};
$('#backupBeforeUpdate').onclick=()=>$('#exportBackup').onclick();
$('#checkUpdate').onclick=async()=>{const button=$('#checkUpdate');button.disabled=true;updateCheckResult='checking';renderOfflineStatus();$('#updateInfo').textContent='正在確認發布版本…';try{const url=globalThis.SHIJU_QUOTES?'https://words-daily-bookmark.lastdeer.chatgpt.site/version.json':'./version.json';const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw Error();const info=await response.json();if(!info||typeof info.appVersion!=='string'||!/^\d+\.\d+\.\d+$/.test(info.appVersion)||!Array.isArray(info.releaseNotes)||!info.releaseNotes.every(v=>typeof v==='string'&&v.length<=200))throw Error();latestVersionInfo=info;updateCheckResult='success';$('#updateInfo').textContent=`目前發布版本：${info.appVersion}；這份 App：${APP_VERSION}。${versionMessage(info.appVersion)} ${info.releaseNotes.join('；')}`;}catch{updateCheckResult='error';$('#updateInfo').textContent='目前無法確認發布版本。請連線後開啟網站查看更新；這份離線版仍可正常使用。';}finally{button.disabled=false;renderOfflineStatus();}};


function buildTypePool(kind){const items=bank.filter(q=>q.kind===kind);if(kind!=='原創觀點')return items;const parents=items.filter(q=>q.parenting),others=items.filter(q=>!q.parenting),pool=[];for(let i=0;i<Math.max(parents.length,Math.ceil(others.length/2));i++){pool.push(...others.slice(i*2,i*2+2));if(parents[i])pool.push(parents[i]);}return pool}
function parentAgeMatches(q,value){return value==='all'||['early','late'].includes(value)&&['all',value].includes(q.dialogue.studyStage)}
$('#parentAge').onchange=()=>{page=0;render()};
function validateReadingSchedules(value){const result={};for(const [date,ids] of Object.entries(requireMap(value,'日期排程'))){if(!validDay(date)||!Array.isArray(ids)||ids.length!==20||new Set(ids).size!==20||!ids.every(validQuoteId))throw Error('日期排程格式不正確。');if(bank.length&&!kinds.every(kind=>ids.filter(id=>itemById(id)?.kind===kind).length===5))throw Error('日期排程需四類各 5 則。');result[date]=ids.slice();}return result}
function cleanReadingSchedules(value){try{return validateReadingSchedules(value)}catch{return {}}}
function withLegacySchedules(logs,plans){const result={...plans};for(const date of Object.keys(requireMap(logs,'閱讀紀錄'))){if(!validDay(date)||result[date])continue;const n=Math.floor(Date.parse(date)/86400000),slot=((n%200)+200)%200;result[date]=kinds.flatMap(kind=>bank.filter(q=>q.id<4000&&q.kind===kind).slice(slot*5,slot*5+5).map(q=>q.id));}return result}
function plannedDaily(date){if(!readingSchedules[date])return selectDaily(Math.floor(Date.parse(date)/86400000));return kinds.flatMap(kind=>readingSchedules[date].map(itemById).filter(q=>q?.kind===kind).sort((a,b)=>recommendationScore(b)-recommendationScore(a)||a.id-b.id))}
$('#workAudience').onchange=()=>{page=0;render()};


function toneMarkup(dialogue){if(!dialogue.tones)return '<p>'+escapeHTML(dialogue.after)+'</p>';return `<div id="toneChoices" class="tone-choices" role="group" aria-label="回應語氣">${Object.entries(dialogue.tones).map(([id,tone])=>`<button class="quiet" data-tone="${id}" aria-pressed="${id==='direct'}">${escapeHTML(tone.label)}</button>`).join('')}</div><p id="toneResponse">${escapeHTML(dialogue.tones.direct.text)}</p><p id="toneUseWhen" class="tone-context">${escapeHTML(dialogue.tones.direct.useWhen)}</p>`;}
function validatePracticeUseRecords(value){if(value===undefined)return [];if(!Array.isArray(value)||value.length>1000)throw Error('使用經驗格式不正確或超過 1,000 筆。');return value.map(item=>{if(!item||typeof item.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(item.id)||typeof item.practiceId!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(item.practiceId)||!isTimestamp(item.createdAt)||!validDay(item.usedOn)||typeof item.situation!=='string'||!item.situation.trim()||item.situation.length>1000||typeof item.response!=='string'||item.response.length>2000||typeof item.next!=='string'||item.next.length>1000||!(item.quoteId===null||validQuoteId(item.quoteId)))throw Error('使用經驗內容或日期格式不正確。');return {id:item.id,practiceId:item.practiceId,createdAt:item.createdAt,usedOn:item.usedOn,situation:item.situation,response:item.response,next:item.next,quoteId:item.quoteId};})}
function cleanPracticeUseRecords(value){try{return validatePracticeUseRecords(value)}catch{return []}}
function mergePracticeUseRecords(current,incoming){const ids=new Set(current.map(x=>x.id)),keys=new Set(current.map(x=>JSON.stringify([x.practiceId,x.usedOn,x.situation,x.response,x.next])));const result=[...current];for(const record of incoming||[]){const key=JSON.stringify([record.practiceId,record.usedOn,record.situation,record.response,record.next]);if(ids.has(record.id)||keys.has(key))continue;result.push(record);ids.add(record.id);keys.add(key);}if(result.length>1000)throw Error('合併後使用經驗超過 1,000 筆。');return result.sort((a,b)=>a.createdAt.localeCompare(b.createdAt));}
function openPracticeUse(id){if(editingUsePractice&&!$('#practiceUseEditor').hidden){const current={practiceId:editingUsePractice,usedOn:$('#useDate').value,situation:$('#useSituation').value.trim(),response:$('#useResponse').value.trim(),next:$('#useNext').value.trim()};if((current.situation||current.response||current.next)&&!practiceUseRecords.some(r=>['practiceId','usedOn','situation','response','next'].every(k=>r[k]===current[k]))){$('#practiceUseStatus').textContent='這筆使用經驗尚未儲存，請先儲存或取消，再選擇其他練習。';return}}const item=practiceHistory.find(r=>r.id===id);if(!item)return;editingUsePractice=id;$('#practiceUseEditor').hidden=false;$('#usePracticeLabel').textContent='對應練習：'+(item.after||item.before).slice(0,150);$('#useDate').value=day;$('#useDate').max=day;$('#useSituation').value='';$('#useResponse').value='';$('#useNext').value='';$('#practiceUseStatus').textContent='';$('#practiceUseEditor').scrollIntoView?.({behavior:'smooth',block:'start'});$('#useSituation').focus();}
$('#savePracticeUse').onclick=()=>{const item=practiceHistory.find(r=>r.id===editingUsePractice);if(!item)return;const usedOn=$('#useDate').value,situation=$('#useSituation').value.trim(),response=$('#useResponse').value.trim(),next=$('#useNext').value.trim();if(!validDay(usedOn)||usedOn>day||!situation){$('#practiceUseStatus').textContent='請填寫今天或以前的使用日期，以及使用場合。';return}try{const record=validatePracticeUseRecords([{id:'use_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8),practiceId:item.id,createdAt:new Date().toISOString(),usedOn,situation,response,next,quoteId:item.quoteId}])[0];const records=mergePracticeUseRecords(practiceUseRecords,[record]);localStorage.setItem('shiju-v1',JSON.stringify({...snapshot(),practiceUseRecords:records}));practiceUseRecords=records;$('#practiceUseStatus').textContent='使用經驗已儲存，會納入每週回顧與備份。';renderPracticeUses();}catch{$('#practiceUseStatus').textContent='未儲存，請檢查內容長度、筆數或瀏覽器儲存空間。'}};
$('#cancelPracticeUse').onclick=()=>{editingUsePractice=null;$('#practiceUseEditor').hidden=true;};
function renderPracticeUses(){const records=[...practiceUseRecords].sort((a,b)=>b.usedOn.localeCompare(a.usedOn)||b.createdAt.localeCompare(a.createdAt)).slice(0,practiceUseLimit);$('#practiceUseHistory').innerHTML=records.length?records.map(r=>`<details class="use-record"><summary>${escapeHTML(r.usedOn)} · ${escapeHTML(r.situation)}</summary><p><b>對方的回應：</b>${escapeHTML(r.response||'（尚未記錄）')}</p><p><b>下次調整：</b>${escapeHTML(r.next||'（尚未記錄）')}</p></details>`).join('')+(practiceUseRecords.length>records.length?'<button class="quiet" id="moreUseRecords">載入更多使用經驗</button>':''):'<p>還沒有實際使用紀錄。從練習歷史選一筆，按「記錄實際使用」。</p>';}
function setOfflineState(status){offlineState={status,checkedAt:new Date().toISOString()};renderOfflineStatus()}
function versionMessage(version){const a=version.split('.').map(Number),b=APP_VERSION.split('.').map(Number);for(let i=0;i<3;i++){if(a[i]>b[i])return '有較新的發布版本，可先備份再更新。';if(a[i]<b[i])return '這份 App 比目前查到的發布版本新，請核對發布說明。';}return '版本一致。';}
function renderOfflineStatus(){const messages={checking:'正在準備或確認離線資料…',ready:'已可離線使用：本版完整資源已備妥',incomplete:'離線資料尚未完成，請連線後重新確認',unverified:'目前無法驗證離線快取，可使用獨立下載版',standalone:'獨立離線檔：已內含完整 6,000 則句庫'};const text=messages[offlineState.status]||messages.unverified;$('#offlineStatus').textContent=text;$('#offlinePreparationStatus').textContent=text;$('#offlineCheckTime').textContent=offlineState.checkedAt?'最近確認：'+new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',dateStyle:'medium',timeStyle:'short'}).format(new Date(offlineState.checkedAt)):'';$('#networkState').textContent=typeof navigator==='undefined'?'尚未取得裝置網路狀態':navigator.onLine?'裝置回報已連線（不代表更新查詢一定成功）':'裝置回報離線';const installed=typeof navigator!=='undefined'&&(navigator.standalone===true||typeof matchMedia==='function'&&matchMedia('(display-mode: standalone)').matches);$('#launchMode').textContent=globalThis.SHIJU_QUOTES?'獨立 HTML 檔':installed?'主畫面／獨立視窗開啟':'一般瀏覽器開啟';$('#updateStatusSummary').textContent=updateCheckResult==='checking'?'正在查詢發布版本':updateCheckResult==='error'?'本次無法確認發布版本':updateCheckResult==='success'&&latestVersionInfo?'發布 '+latestVersionInfo.appVersion+' · '+versionMessage(latestVersionInfo.appVersion):'尚未確認發布版本';}
async function verifyOfflineReadiness(){if(Array.isArray(globalThis.SHIJU_QUOTES)&&globalThis.SHIJU_QUOTES.length===6000){setOfflineState('standalone');return true}setOfflineState('checking');try{if(typeof caches==='undefined'||!(await caches.keys()).includes(OFFLINE_CACHE_NAME)){setOfflineState('incomplete');return false}const cache=await caches.open(OFFLINE_CACHE_NAME);const paths=['./','./index.html','./style.css','./app.js','./quotes.json','./manifest.webmanifest','./icon-192.png','./icon-512.png','./apple-touch-icon.png','./source-license.txt','./library-report.json'];const resources=await Promise.all(paths.map(p=>cache.match(new URL(p,location.href).href)));if(resources.some(r=>!r?.ok)){setOfflineState('incomplete');return false}const data=await resources[4].clone().json(),html=await resources[1].clone().text(),js=await resources[3].clone().text();const complete=Array.isArray(data)&&data.length===6000&&kinds.every(k=>data.filter(q=>q.kind===k).length===1500)&&html.includes('id="featured"')&&js.includes("APP_VERSION='"+APP_VERSION+"'");setOfflineState(complete?'ready':'incomplete');return complete;}catch{setOfflineState('unverified');return false}}
$('#practiceUseHistory').addEventListener('click',e=>{if(e.target.closest('#moreUseRecords')){practiceUseLimit+=20;renderPracticeUses();}});
$('#verifyOffline').onclick=verifyOfflineReadiness;
if(typeof globalThis.addEventListener==='function'){globalThis.addEventListener('online',renderOfflineStatus);globalThis.addEventListener('offline',renderOfflineStatus);}
function isStandaloneMode(){return typeof navigator!=='undefined'&&(navigator.standalone===true||typeof matchMedia==='function'&&matchMedia('(display-mode: standalone)').matches)}
function applyInstallEntry(){if(globalThis.SHIJU_QUOTES||typeof URLSearchParams==='undefined')return;const params=new URLSearchParams(location.search||'');if(params.get('install')!=='1')return;setView('settings');$('#installPanel').open=true;$('#installPanel').scrollIntoView?.({block:'start'});}
applySettings();init();
